import json,sys
P=json.load(open('plan.json'))['plan']
NM={(0,0):'top-left',(1,0):'top-right',(0,1):'bottom-left',(1,1):'bottom-right'}
def side(qs,w):
    s=sorted(NM[(x-w[0],y-w[1])] for x,y in qs)
    m={('top-left','top-right'):'top half',('bottom-left','bottom-right'):'bottom half',('bottom-left','top-left'):'left half',('bottom-right','top-right'):'right half'}
    return m.get(tuple(s),' and '.join(f'{x} quarter' for x in s))
def prompt(k):
    p=P[k];w=p['win'];ctx=side(p['ctx'],w);new=side(p['new'],w)
    return f"""Continue an illustrated isometric map seamlessly. Output a square image with exactly the same framing as the input, pixel-aligned to it. The {ctx} of the input is ALREADY FINISHED artwork: keep it pixel-identical, do not repaint, recolour, sharpen or shift it. The {new} of the input is still a raw 3D render of the same 5th-century Late Roman (early Byzantine) harbour town: small low-rise houses with pitched tile roofs, lanes, small squares, trees. Repaint ONLY that raw part in exactly the same illustrated style, colours, lighting and shadow length as the finished part, so that the two join with no visible seam: roads, house rows and colours continue straight across the boundary. Style: clean illustrated isometric city-builder tile (Isometric SF, 1990s SimCity 4), crisp outlines, flat-shaded faces, soft even daylight from the upper left, short soft shadows instead of long dark shadows; match the finished part's colours exactly: deep terracotta and brick-red roofs, cream walls, warm saturated honey-yellow open ground, grey-beige stone lanes, dark cypress and olive greens; same brightness and saturation as the finished part, do not lighten, wash out or desaturate. Flat blue-green water stays flat blue-green water; the flat cream-beige area is an empty paper margin, NOT sea: keep it plain flat cream-beige and do not paint water, shore, jetties or boats there or next to it; the town's edge against that margin is dry land with houses. STRICT GEOMETRY LOCK: every building keeps exactly its position, footprint, orientation and height; every lane, square, shoreline, mole and jetty stays exactly where it is. Do not add or remove buildings, do not merge blocks, no towers, domes, walls, skyscrapers or new landmarks; keep the few large existing buildings (warehouses, colonnades, a forum) as they are. No modern objects, no cars, no glass, no text, no labels, no watermark, no border."""
if __name__=='__main__':print(prompt(int(sys.argv[1])))
